// ============================================================
// FORM PROMPT BUILDER — n8n Code Node
// Version 2.0 — Fixed: role conflict, thinking tag, lang fallback,
//               brace escaping, question count & type rules
// ============================================================

const input = $input.first().json.body || $input.first().json;

// ────────────────────────────────────────────────────────────
// 1. LANGUAGE MAPPING
//    Fix: French was the silent fallback for ALL unknown locales.
//    Now defaults to English. Add any locale you need.
// ────────────────────────────────────────────────────────────
const LANGUAGE_MAP = {
  en: 'English',  fr: 'French',   es: 'Spanish',
  ar: 'Arabic',   pt: 'Portuguese', de: 'German',
  it: 'Italian',  nl: 'Dutch',    tr: 'Turkish',
  ru: 'Russian',  zh: 'Chinese',  ja: 'Japanese',
  pl: 'Polish',   sv: 'Swedish',  ko: 'Korean'
};
const language = LANGUAGE_MAP[input.locale] || 'English';

// ────────────────────────────────────────────────────────────
// 2. CONSULTANT PROFILE
// ────────────────────────────────────────────────────────────
const consultant    = input.consultant_profile || {};
const consultantName    = consultant.full_name   || 'Consultant';
const consultantRole    = consultant.job_title   || 'Expert consultant';
const consultantBio     = consultant.bio         || '';
const consultantWebsite = consultant.website     || '';
const consultantSocial  = consultant.social_networks || {};

// ────────────────────────────────────────────────────────────
// 3. ACTIVE SERVICE
// ────────────────────────────────────────────────────────────
const service          = input.active_service || null;
const serviceIsActive  = !!(service && service.name);
const serviceDescription  = serviceIsActive ? (service.description  || '') : '';
const serviceBasePrompt   = serviceIsActive ? (service.base_prompt  || '') : '';

// ────────────────────────────────────────────────────────────
// 4. SYSTEM BLOCK
//    Fix: previously <system> and <persona> carried two competing
//    identities. Now merged into one coherent authority block.
//    The consultant persona is a TONE constraint, not an identity override.
// ────────────────────────────────────────────────────────────
let systemContent;

if (serviceIsActive && serviceBasePrompt) {
  // When a service has its own base prompt, it becomes the core instruction.
  // We append the CRO mission as a reinforcement layer, not a replacement.
  systemContent =
    serviceBasePrompt
    + (serviceDescription ? `\n\nService context: ${serviceDescription}` : '')
    + `\n\nCore mission: You are acting as a UX/CRO Form Architect in service of the above. `
    + `Generate a high-converting lead qualification form that perfectly fits this service's audience.`;
} else {
  // Default: unified role that combines expertise + consultant identity
  systemContent =
    `You are an elite Lead Generation Form Architect and UX/CRO specialist. `
    + `You operate on behalf of ${consultantName}, ${consultantRole}. `
    + `Your sole mission is to design high-converting prospect qualification forms that: `
    + `(1) reflect ${consultantName}'s domain expertise, `
    + `(2) minimize cognitive friction for prospects, `
    + `(3) collect the highest-quality data for lead scoring and follow-up.`;
}

// ────────────────────────────────────────────────────────────
// 5. INSTRUCTIONS BLOCK
//    Includes: UX architecture, question count rules,
//    type selection rules, label writing rules, output format.
//    Fix: removed <thinking> tag instruction that broke JSON parsing.
//    The model now reasons internally before outputting JSON.
// ────────────────────────────────────────────────────────────
const instructionsContent = `
Generate a complete, production-ready JSON form for lead generation and prospect qualification.
Reason internally about the best UX strategy for this specific domain, then output ONLY the JSON — no preamble, no explanation, no markdown fences.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
MANDATORY FORM ARCHITECTURE
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

SECTION STRUCTURE — Always follow this 3-section chronological order:

  ① DISCOVERY (first section)
     Purpose: Engagement. Start with the prospect's situation and pain points.
     Tone: Easy, empathetic, conversational. No commitment required.
     Question types: radio, checkbox, select — never open text here.
     Question count: 3 to 4 questions.

  ② PROJECT DETAILS (second section)
     Purpose: Qualification. Go deeper on need, timeline, budget, scope.
     Tone: Direct but friendly. The prospect is already invested.
     Question types: radio, select, checkbox, and exactly ONE textarea for a critical deep-dive.
     Question count: 3 to 5 questions.

  ③ PERSONAL INFORMATION (third and last section — ALWAYS at the end)
     Purpose: Data capture. The prospect commits their contact details only after
     they've engaged with the form (foot-in-the-door principle).
     Question count: EXACTLY 3 to 4 questions in this order:
       - Full Name (type: text, required: true)
       - Professional Email (type: email, required: true)
       - Phone Number (type: phone, required: true)
       - Company / Organization (type: text, required: false) — include only if relevant to the domain

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
QUESTION COUNT RULES
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  - Total questions (excluding section headers): minimum 9, maximum 13.
  - Section ① Discovery: 3 to 4 questions.
  - Section ② Project Details: 3 to 5 questions (including the single textarea).
  - Section ③ Personal Info: exactly 3 to 4 questions.
  - Never exceed 13 questions total — completion rate drops sharply beyond this.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
QUESTION TYPE SELECTION RULES
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  Choose the type that creates the LEAST friction for the expected answer:

  "radio"    → Use when: only ONE answer is valid, 2 to 4 options.
               Best for: budget ranges, timelines, yes/no, priority levels.
               Example: "What is your current timeline?" → [Under 1 month / 1–3 months / 3–6 months / Not sure]

  "checkbox" → Use when: MULTIPLE answers are valid simultaneously, 2 to 5 options.
               Best for: goals, challenges, services of interest, preferred channels.
               Example: "What are your main challenges?" → [Lack of time / Budget constraints / No strategy / ...]

  "select"   → Use when: only ONE answer is valid BUT there are 5 or more options (rendered as dropdown).
               Best for: industry sector, country, company size, type of business.
               Example: "What industry are you in?" → [Technology / Healthcare / Finance / Real estate / ...]

  "textarea" → Use MAXIMUM ONE time per form, only in Section ②, for the single most important open question.
               Best for: "Describe your main challenge in a few words."
               Keep the label under 8 words. Set required: false to reduce friction.

  "text"     → ONLY for: Full Name, Company Name. Never for anything else.
  "email"    → ONLY for: Email Address field.
  "phone"    → ONLY for: Phone Number field.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
LABEL & OPTIONS WRITING RULES
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  Labels:
  - HARD LIMIT: maximum 8 words per label.
  - Use conversational, first-person-friendly language.
  - Start with "What", "Which", "How", "Do you", "Are you" — not with nouns.
  - GOOD: "What is your main goal right now?"
  - BAD:  "Primary strategic objective (please specify)"
  - GOOD: "How soon do you need results?"
  - BAD:  "Expected implementation timeline"

  Options (for radio / checkbox / select):
  - HARD LIMIT: maximum 5 words per option.
  - Always add a catch-all when relevant: "Not sure yet", "Other", "None of the above".
  - Options must be mutually exclusive for radio/select.
  - Maximum 4 options for radio, maximum 5 for checkbox, maximum 10 for select.
  - Never include an "Other — please specify" option without a follow-up text field.

  Placeholder text:
  - Only include for text, textarea, email, phone types.
  - Keep under 6 words.
  - Use it as a micro-instruction: "e.g. John Smith", "your work email", "+1 (555) 000-0000".

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
FORM TITLE & DESCRIPTION
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  form_title:       MAX 6 words. Action-oriented. Benefit-focused. No jargon.
  form_description: MAX 30 words. Lead with the value for the prospect (what they GET).
                    End with a clear expectation ("takes 2 minutes", "free consultation", etc.).

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
THANK YOU PAGE
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  thank_you_title:       MAX 4 words. Reassuring and positive. (e.g., "Request Received!", "You're All Set")
  thank_you_description: MAX 30 words. State EXACTLY what happens next AND when.
                         Example: "I'll review your answers and reach out within 24 hours to schedule your free strategy call."

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
EXECUTION RULES
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  - ALL user-visible text MUST be generated in ${language}.
  - If the form objective is vague, infer the domain and typical prospect pain points
    from the consultant's role and bio. Tailor EVERY question to that professional context.
  - A question that could belong on ANY form is a bad question. Each question should feel
    specific to the consultant's domain.
  - Output ONLY a valid raw JSON object. No preamble. No explanation. No markdown. Just JSON.
`.trim();

// ────────────────────────────────────────────────────────────
// 6. OUTPUT FORMAT SCHEMA
//    Fix: built as an array of strings and joined WITHOUT going
//    through the brace-escaping step. This prevents the model
//    from seeing {{ }} in the example and reproducing them.
// ────────────────────────────────────────────────────────────
const outputFormatLines = [
  '{',
  '  "form_title": "string (max 6 words)",',
  '  "form_description": "string (max 30 words)",',
  '  "questions": [',
  '',
  '    // ── Section header example ──',
  '    {',
  '      "type": "section",',
  '      "sectionTitle": "Section Name",',
  '      "label": "",',
  '      "required": false',
  '    },',
  '',
  '    // ── Closed question examples ──',
  '    {',
  '      "type": "radio",',
  '      "label": "Question label (max 8 words)",',
  '      "options": ["Option A", "Option B", "Not sure yet"],',
  '      "required": true',
  '    },',
  '    {',
  '      "type": "checkbox",',
  '      "label": "Which of these apply to you?",',
  '      "options": ["Goal 1", "Goal 2", "Goal 3", "Other"],',
  '      "required": false',
  '    },',
  '    {',
  '      "type": "select",',
  '      "label": "What industry are you in?",',
  '      "placeholder": "Select your industry",',
  '      "options": ["Option 1", "Option 2", "Option 3", "Option 4", "Option 5"],',
  '      "required": true',
  '    },',
  '',
  '    // ── Single textarea (Section 2 only, max 1 per form) ──',
  '    {',
  '      "type": "textarea",',
  '      "label": "Describe your main challenge briefly.",',
  '      "placeholder": "A few words is enough",',
  '      "required": false',
  '    },',
  '',
  '    // ── Personal Info section examples ──',
  '    {',
  '      "type": "text",',
  '      "label": "Your full name",',
  '      "placeholder": "e.g. Jane Smith",',
  '      "required": true',
  '    },',
  '    {',
  '      "type": "email",',
  '      "label": "Your professional email address",',
  '      "placeholder": "you@company.com",',
  '      "required": true',
  '    },',
  '    {',
  '      "type": "phone",',
  '      "label": "Your phone number",',
  '      "placeholder": "+1 (555) 000-0000",',
  '      "required": true',
  '    }',
  '',
  '  ],',
  '  "thank_you_title": "string (max 4 words)",',
  '  "thank_you_description": "string (max 30 words)",',
  '  "button_text": "Action button label (max 3 words, e.g. Start audit)"',
  '}'
];
const outputFormatContent = outputFormatLines.join('\n');

// ────────────────────────────────────────────────────────────
// 7. CONTEXT BLOCK
// ────────────────────────────────────────────────────────────
let contextContent = `CONSULTANT PROFILE:
  Name: ${consultantName}
  Role: ${consultantRole}`;

if (consultantBio)              contextContent += `\n  Bio: ${consultantBio}`;
if (consultantWebsite)          contextContent += `\n  Website: ${consultantWebsite}`;
if (consultantSocial?.linkedin) contextContent += `\n  LinkedIn: ${consultantSocial.linkedin}`;

contextContent += `\n\n=== FORM REQUEST ===`;
contextContent += `\nObjective: ${input.prompt || 'Generate a prospect qualification and lead generation form'}`;

if (input.form_title?.trim())
  contextContent += `\nPreferred Title (use as creative reference, not verbatim): ${input.form_title}`;

if (input.form_description?.trim())
  contextContent += `\nPreferred Description (use as reference): ${input.form_description}`;

if (Array.isArray(input.sections) && input.sections.length > 0) {
  contextContent += '\n\nClient-suggested Sections (adapt to UX architecture above):';
  input.sections.forEach(s => {
    contextContent += `\n  - ${s.name}`;
    if (s.description) contextContent += `: ${s.description}`;
  });
}

// ────────────────────────────────────────────────────────────
// 8. ASSEMBLY & N8N SAFETY
//    Fix: brace-escaping is applied ONLY to dynamic user-input
//    parts (systemContent and contextContent), which may contain
//    { } characters from user-provided bios, prompts, etc.
//
//    instructionsContent and outputFormatContent are static and
//    controlled — escaping them would corrupt the JSON schema
//    example shown to the model.
// ────────────────────────────────────────────────────────────
const safeSystem  = systemContent.replace(/\{/g, '{{').replace(/\}/g, '}}');
const safeContext = contextContent.replace(/\{/g, '{{').replace(/\}/g, '}}');

const generatedPrompt =
  `<system>\n${safeSystem}\n</system>\n\n` +
  `<instructions>\n${instructionsContent}\n</instructions>\n\n` +
  `<output_format>\n${outputFormatContent}\n</output_format>\n\n` +
  `<context>\n${safeContext}\n</context>`;

return [{
  json: {
    ...input,
    generated_prompt: generatedPrompt
  }
}];

let text = $input.first().json.text || '';
text = text.replace(/<thinking>[\s\S]*?<\/thinking>/gi, '');
text = text.replace(/^```json\n?/, '').replace(/\n?```$/, '');
text = text.replace(/^```\n?/, '').replace(/\n?```$/, '');
text = text.trim();

// FIX: Extract JSON between first { and last } for robustness
const start = text.indexOf('{');
const end   = text.lastIndexOf('}');
if (start !== -1 && end > start) {
  text = text.substring(start, end + 1);
}

let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  // FIX: throw instead of returning a fake form.
  // Previously, a parse error returned { form_title: 'Error Form', questions: [] }
  // which then got saved to Supabase as a real form — silent data corruption.
  throw new Error('JSON_PARSE_ERROR: Gemini returned invalid JSON. Raw output: ' + text.substring(0, 200));
}

// FIX: Validate that the parsed object has the minimum required structure
if (!parsed.form_title || !Array.isArray(parsed.questions) || parsed.questions.length === 0) {
  throw new Error('JSON_SCHEMA_ERROR: Generated form is missing required fields (form_title or questions).');
}

const questions = Array.isArray(parsed.questions) ? parsed.questions : [];
const sections = questions.filter(q => q.type === 'section');

return [{
  json: {
    form_title: parsed.form_title || 'Untitled Form',
    form_description: parsed.form_description || '',
    questions: questions,
    sections: sections,
    thank_you_title: parsed.thank_you_title || 'Thank you!',
    thank_you_description: parsed.thank_you_description || '',
    button_text: parsed.button_text || 'Envoyer',
    generated: true
  }
}];

const payload = $('Webhook Trigger Form AI').first().json.body;
const parsed = $input.first().json;
const consultant = payload.consultant_profile || {};

// Generate slug from form_title (lowercase, replace spaces with dashes)
const generateSlug = (title) => {
  return (title || 'form').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
};

const slug = generateSlug(parsed.form_title) + '_' + Date.now();

return [{
  json: {
    user_id: payload.user_id,
    title: parsed.form_title || 'Untitled Form',
    slug: slug,
    status: 'published',
    form_structure: {
      form_title: parsed.form_title || 'Untitled Form',
      form_description: parsed.form_description || '',
      questions: parsed.questions || [],
      sections: parsed.sections || [],
      thank_you_title: parsed.thank_you_title || 'Merci!',
      thank_you_description: parsed.thank_you_description || '',
      button_text: parsed.button_text || 'Envoyer'
    },
    ai_config: payload.ai_config || {},
    consultant_email: payload.user_email || 'contact@pretalk.me',
    consultant_name: consultant.full_name || payload.user_name || 'Consultant',
    consultant_role: consultant.job_title || 'Consultant Expert',
    domain: consultant.website || null,
    views_count: 0,
    leads_count: 0
  }
}];
